107	        .take(top_k)
108	        .collect();
109	
110	    for hit in search_sessions_by_name(query) {
111	        let already = hits.iter().any(|h| {
112	            matches!(h.kind, HitKind::Session) && h.session_id == hit.session_id
113	        });
114	        if !already { hits.insert(0, hit); }
115	    }
116	    for hit in search_repos_by_name(query) {
117	        let already = hits.iter().any(|h| {
118	            matches!(h.kind, HitKind::Repo) && h.repo_dir == hit.repo_dir
119	        });
120	        if !already { hits.insert(0, hit); }
121	    }
122	    hits.truncate(top_k);
123	    enrich_hits(&mut hits);
124	
125	    let groups = build_groups(hits);
126	
127	    if json || !io::stdout().is_terminal() {
128	        let arr: Vec<serde_json::Value> = groups.iter().map(|g| {
129	            let hits_json: Vec<serde_json::Value> = g.rows.iter().map(|r| serde_json::json!({
130	                "timestamp": r.hit_ts,
131	                "excerpt": r.lines.join(" "),
132	            })).collect();
133	            serde_json::json!({
134	                "kind": g.kind.label(),
135	                "session_id": g.session_id,
136	                "session_name": g.title,
137	                "dir": g.dir,
138	                "branch": g.branch,
139	                "agent": g.agent,
140	                "updated_at": g.updated_at,
141	                "backed_up": g.backed_up,
142	                "remote": g.remote,
143	                "hits": hits_json,
144	            })
145	        }).collect();
146	        println!("{}", serde_json::to_string_pretty(&serde_json::json!({
147	            "query": query,
148	            "results": arr,
149	        }))?);
150	        return Ok(());
151	    }
152	
153	    let orig_hook = std::panic::take_hook();
154	    std::panic::set_hook(Box::new(move |info| {
155	        let mut out = io::stdout();
156	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
157	        let _ = terminal::disable_raw_mode();
158	        orig_hook(info);
159	    }));
160	
161	    let mut stdout = io::stdout();
162	    terminal::enable_raw_mode()?;
163	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
164	
165	    let result = tui_loop(&mut stdout, &groups, query, ms);
166	
167	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
168	    terminal::disable_raw_mode()?;
169	
170	    result
171	}
